<script setup lang="ts">
import {nextTick,onMounted,onBeforeUnmount,ref} from 'vue';import type {RequestFn} from './media';import {date,money,states} from './lib';
const props=defineProps<{kind:string,target:Record<string,any>,request:RequestFn}>();const emit=defineEmits<{close:[]}>();
const result=ref<Record<string,any>>({items:[],summary:{}}),offset=ref(0),busy=ref(false),error=ref('');let active=true,sequence=0;
async function load(next=offset.value){const serial=++sequence;busy.value=true;error.value='';try{const data=await props.request(`admin/${props.kind}/${props.target.id}/usage?offset=${next}`);if(active&&serial===sequence){result.value=data;offset.value=next}}catch(e){if(active&&serial===sequence)error.value=String(e instanceof Error?e.message:e)}finally{if(active&&serial===sequence)busy.value=false}}
const dialog=ref<HTMLElement>();let previousFocus:HTMLElement|null=null;
function key(e:KeyboardEvent){if(e.key==='Escape'){emit('close');return}if(e.key!=='Tab')return;const buttons=Array.from(dialog.value?.querySelectorAll<HTMLButtonElement>('button:not([disabled])')||[]),first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}
onMounted(async()=>{previousFocus=document.activeElement as HTMLElement;await nextTick();dialog.value?.querySelector<HTMLButtonElement>('button')?.focus();document.addEventListener('keydown',key);void load()});onBeforeUnmount(()=>{active=false;sequence++;document.removeEventListener('keydown',key);if(previousFocus?.isConnected)previousFocus.focus()});
</script>
<template><div class="modal-backdrop"><section ref="dialog" class="modal usage-dialog" role="dialog" aria-modal="true" aria-label="代码使用记录"><div class="section-head"><div><span class="eyebrow">{{kind==='coupons'?'COUPON':'INVITATION'}} HISTORY</span><h2>使用记录 · {{target.name||target.prefix}}</h2></div><button aria-label="关闭使用记录" @click="emit('close')">×</button></div><p v-if="error" class="alert error">{{error}}</p><p class="usage-summary">剩余 <strong>{{result.summary.remaining_uses??'不限'}}</strong> 次 · 已占用 {{result.summary.used_uses??'—'}} / {{result.summary.max_uses||'不限'}} <span v-if="kind==='coupons'">（待付款占用 {{result.summary.reserved_uses??0}} 次）</span><span v-else>（已验证 {{result.summary.verified_uses??0}} 次）</span></p><p class="muted">{{kind==='coupons'?'待付款预占次数；取消后释放，退款不返还次数。记录包含未计次的历史订单。':'注册后预占名额；邮箱验证完成后计为已使用，未验证到期由后台任务释放。删除账户不返还已使用次数。'}}按时间从新到旧显示，每页 25 条。</p><div class="usage-records" :aria-busy="busy"><article v-for="r in result.items" :key="r.id" class="usage-record"><div class="section-head"><strong>{{r.name}} <small>{{r.email}}</small></strong><span class="badge">{{kind==='coupons'?(states[r.state]||r.state):r.released?'已释放':r.finalized?'已验证':'待验证占位'}}</span></div><small>{{date(r.created_at)}}<span v-if="r.customer_deleted_at"> · 账户已删除</span></small><template v-if="kind==='coupons'"><p>减免 {{money(r.discount_amount)}} · 实付 {{money(r.payable)}} · {{r.counts_toward_limit?'计入使用上限':'不占用次数'}}</p><small class="mono">订单 {{r.id}}</small></template><small v-else-if="r.finalized">验证时间 {{date(r.email_verified_at)}}</small><small v-else-if="!r.released">预占截止 {{date(r.expires_at)}}</small></article><p v-if="!result.items.length&&!busy" class="empty">暂无使用记录</p></div><div class="usage-pagination"><button :disabled="busy||offset===0" @click="load(Math.max(0,offset-25))">上一页</button><span>第 {{Math.floor(offset/25)+1}} 页 · 共 {{result.total??0}} 条</span><button :disabled="busy||offset+25>=result.total" @click="load(offset+25)">下一页</button><button :disabled="busy" @click="load()">刷新</button></div></section></div></template>
<style scoped>.usage-dialog{width:min(800px,100%)}.usage-summary{padding:13px;background:var(--accent-soft);border-radius:9px}.usage-records{max-height:50dvh;overflow:auto;overscroll-behavior:contain}.usage-record{padding:16px 3px;border-bottom:1px solid var(--border)}.usage-record small{display:block;overflow-wrap:anywhere}.usage-record .section-head{margin:0 0 5px}.usage-record p{margin:6px 0;font-size:12px}.usage-pagination{display:flex;align-items:center;justify-content:center;gap:12px;flex-wrap:wrap;padding-top:18px}.usage-pagination span{font-size:12px}@media(max-width:760px){.usage-pagination{gap:7px}.usage-pagination button{padding:8px 10px}.usage-records{max-height:48dvh}}</style>
